-- Dedicated Memocious schemas. No changes to unrelated application tables.
create schema memocious;
create schema memocious_private;
revoke all on schema memocious, memocious_private from public, anon, authenticated;
grant usage on schema memocious, memocious_private to service_role;
create table memocious_private.admin_users (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id uuid not null unique references auth.users(id) on delete restrict, role text not null check(role in ('owner','editor')), active boolean not null default true, mfa_required boolean not null default true, role_version int not null default 1, revoked_at timestamptz);
alter table memocious_private.admin_users enable row level security;
revoke all on memocious_private.admin_users from public, anon, authenticated;
grant select,insert,update,delete on memocious_private.admin_users to service_role;
create table memocious_private.app_sessions (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), token_hash text not null unique check(char_length(token_hash)=64), user_id uuid references auth.users(id) on delete cascade, provider_reference uuid, audience text not null check(audience in ('customer','admin','guest')), encrypted_tokens text, key_version text, assurance text not null default 'aal1' check(assurance in ('aal1','aal2')), mfa_verified_at timestamptz, last_active_at timestamptz not null default now(), absolute_expires_at timestamptz not null, revoked_at timestamptz, csrf_hash text not null, refresh_lease_until timestamptz, refresh_lease_id uuid, credential_version int not null default 1, check((audience='guest' and user_id is null and encrypted_tokens is null) or (audience<>'guest' and user_id is not null and encrypted_tokens is not null)));
alter table memocious_private.app_sessions enable row level security;
revoke all on memocious_private.app_sessions from public, anon, authenticated;
grant select,insert,update,delete on memocious_private.app_sessions to service_role;
create table memocious_private.auth_attempts (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), token_hash text not null unique, encrypted_verifier text not null, return_path text not null, expires_at timestamptz not null default now()+interval '10 minutes', consumed_at timestamptz);
alter table memocious_private.auth_attempts enable row level security;
revoke all on memocious_private.auth_attempts from public, anon, authenticated;
grant select,insert,update,delete on memocious_private.auth_attempts to service_role;
create table memocious.profiles (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id uuid not null unique references auth.users(id) on delete cascade, full_name text not null default '' check (char_length(full_name)<=120), avatar_ref text, phone text check(phone ~ '^[1-9][0-9]{6,14}$'), verified_at timestamptz);
alter table memocious.profiles enable row level security;
revoke all on memocious.profiles from public, anon, authenticated;
grant select,insert,update,delete on memocious.profiles to service_role;
create table memocious.categories (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), parent_id uuid references memocious.categories(id) on delete restrict, slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), label text not null check(char_length(label) between 1 and 120), icon text not null default 'gift', sort_order int not null default 0, active boolean not null default true, check(parent_id is distinct from id));
alter table memocious.categories enable row level security;
revoke all on memocious.categories from public, anon, authenticated;
grant select,insert,update,delete on memocious.categories to service_role;
create table memocious.occasions (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), parent_id uuid references memocious.occasions(id) on delete restrict, slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), label text not null check(char_length(label) between 1 and 120), icon text not null default 'gift', sort_order int not null default 0, active boolean not null default true, season_start date, season_end date, check(parent_id is distinct from id));
alter table memocious.occasions enable row level security;
revoke all on memocious.occasions from public, anon, authenticated;
grant select,insert,update,delete on memocious.occasions to service_role;
create table memocious.products (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), name text not null check(char_length(name) between 1 and 120), description text not null default '' check(char_length(description)<=500), detail text not null default '' check(char_length(detail)<=10000), materials text not null default '', dimensions text not null default '', price_paise bigint check(price_paise between 0 and 100000000), max_price_paise bigint check(max_price_paise between 0 and 100000000), currency text not null default 'INR' check(currency='INR'), customizable boolean not null default false, colour text not null default 'cream', lead_type text not null default 'made-to-order' check(lead_type in ('ready','made-to-order')), lead_days int check(lead_days>=0), in_stock boolean not null default true, moq int check(moq between 1 and 10000), enterprise boolean not null default false, featured boolean not null default false, active boolean not null default false, publication_state text not null default 'draft' check(publication_state in ('draft','published')), seo_title text, seo_description text, search_vector tsvector generated always as (to_tsvector('english',name||' '||description)) stored, deleted_at timestamptz, version int not null default 1 check(version>0), check(max_price_paise is null or (price_paise is not null and max_price_paise>=price_paise)));
alter table memocious.products enable row level security;
revoke all on memocious.products from public, anon, authenticated;
grant select,insert,update,delete on memocious.products to service_role;
create table memocious.product_images (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), product_id uuid not null references memocious.products(id) on delete cascade, private_path text, public_path text check(public_path ~ '^/media/[a-zA-Z0-9/_-]+[.](webp|avif|png|jpg)$'), alt text not null check(char_length(alt) between 1 and 300), sort_order int not null default 0, width int check(width>0), height int check(height>0), sanitized_at timestamptz, published_at timestamptz, check(published_at is null or (sanitized_at is not null and public_path is not null)));
alter table memocious.product_images enable row level security;
revoke all on memocious.product_images from public, anon, authenticated;
grant select,insert,update,delete on memocious.product_images to service_role;
create table memocious.product_categories (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), product_id uuid not null references memocious.products(id) on delete cascade, category_id uuid not null references memocious.categories(id) on delete restrict, unique(product_id,category_id));
alter table memocious.product_categories enable row level security;
revoke all on memocious.product_categories from public, anon, authenticated;
grant select,insert,update,delete on memocious.product_categories to service_role;
create table memocious.product_occasions (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), product_id uuid not null references memocious.products(id) on delete cascade, occasion_id uuid not null references memocious.occasions(id) on delete restrict, unique(product_id,occasion_id));
alter table memocious.product_occasions enable row level security;
revoke all on memocious.product_occasions from public, anon, authenticated;
grant select,insert,update,delete on memocious.product_occasions to service_role;
create table memocious.product_options (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), product_id uuid not null references memocious.products(id) on delete cascade, kind text not null check(kind in ('colour','size','addon','text','upload')), label text not null check(char_length(label) between 1 and 120), required boolean not null default false, max_length int check(max_length between 0 and 500), max_count int check(max_count between 1 and 20), active boolean not null default true, sort_order int not null default 0, version int not null default 1);
alter table memocious.product_options enable row level security;
revoke all on memocious.product_options from public, anon, authenticated;
grant select,insert,update,delete on memocious.product_options to service_role;
create table memocious.option_values (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), option_id uuid not null references memocious.product_options(id) on delete cascade, label text not null check(char_length(label) between 1 and 120), delta_paise bigint not null default 0 check(delta_paise between 0 and 100000000), active boolean not null default true, sort_order int not null default 0);
alter table memocious.option_values enable row level security;
revoke all on memocious.option_values from public, anon, authenticated;
grant select,insert,update,delete on memocious.option_values to service_role;
create table memocious.orders (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), code text not null unique, user_id uuid references auth.users(id) on delete set null, actor_session_id uuid not null, source text not null check(source in ('product','builder','enterprise')), status text not null default 'inquiry' check(status in ('inquiry','confirmed','payment_received','in_production','quality_check','packed','shipped','out_for_delivery','delivered','on_hold','cancelled','refunded')), version int not null default 1, contact_name text check(char_length(contact_name)<=120), phone text check(phone ~ '^[1-9][0-9]{6,14}$'), pincode text check(pincode ~ '^[0-9]{6}$'), address jsonb, estimate_paise bigint check(estimate_paise between 0 and 1000000000000), confirmed_total_paise bigint check(confirmed_total_paise between 0 and 1000000000000), payment_received_paise bigint not null default 0 check(payment_received_paise>=0), payment_verified_by uuid, payment_verified_at timestamptz, refund_due boolean not null default false, hold_from text, cancellation_reason text, requested_date date, eta date, courier_name text, courier_number text, courier_link text check(courier_link ~ '^https://'), deleted_at timestamptz);
alter table memocious.orders enable row level security;
revoke all on memocious.orders from public, anon, authenticated;
grant select,insert,update,delete on memocious.orders to service_role;
create table memocious.order_items (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), order_id uuid not null references memocious.orders(id) on delete restrict, product_id uuid references memocious.products(id) on delete set null, product_name text not null, unit_price_paise bigint check(unit_price_paise between 0 and 100000000), currency text not null default 'INR' check(currency='INR'), quantity int not null check(quantity between 1 and 10000), option_snapshot jsonb not null default '[]', message text not null default '' check(char_length(message)<=500), moq_snapshot int, immutable_snapshot jsonb not null);
alter table memocious.order_items enable row level security;
revoke all on memocious.order_items from public, anon, authenticated;
grant select,insert,update,delete on memocious.order_items to service_role;
create table memocious.order_events (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), order_id uuid not null references memocious.orders(id) on delete restrict, actor_session_id uuid not null, from_status text, to_status text not null, order_version int not null, customer_note text check(char_length(customer_note)<=2000), internal_note text check(char_length(internal_note)<=2000), customer_photo_id uuid, request_id uuid not null, unique(order_id,order_version));
alter table memocious.order_events enable row level security;
revoke all on memocious.order_events from public, anon, authenticated;
grant select,insert,update,delete on memocious.order_events to service_role;
create table memocious.reviews (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id uuid not null references auth.users(id) on delete restrict, product_id uuid not null references memocious.products(id) on delete restrict, rating int not null check(rating between 0 and 5), body text not null check(char_length(body)<=2000), photo_id uuid, status text not null default 'pending' check(status in ('pending','approved','rejected')), display_first_name text, moderated_by uuid, moderation_note text, moderated_at timestamptz, deleted_at timestamptz, version int not null default 1, unique(user_id,product_id));
alter table memocious.reviews enable row level security;
revoke all on memocious.reviews from public, anon, authenticated;
grant select,insert,update,delete on memocious.reviews to service_role;
