alter table memocious.review_reports enable row level security;
revoke all on memocious.review_reports from public, anon, authenticated;
grant select,insert,update,delete on memocious.review_reports to service_role;
create table memocious.wishlist_items (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id uuid not null references auth.users(id) on delete cascade, product_id uuid not null references memocious.products(id) on delete cascade, unique(user_id,product_id));
alter table memocious.wishlist_items enable row level security;
revoke all on memocious.wishlist_items from public, anon, authenticated;
grant select,insert,update,delete on memocious.wishlist_items to service_role;
