create table memocious.enterprise_inquiries (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), code text not null unique, user_id uuid references auth.users(id) on delete set null, actor_session_id uuid not null, organization text not null check(char_length(organization) between 1 and 120), organization_type text not null check(organization_type in ('college','company','event','ngo','other')), contact_name text not null, contact_role text, phone text not null check(phone ~ '^[1-9][0-9]{6,14}$'), email text not null check(char_length(email)<=254), gstin text check(gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$'), items jsonb not null, branding jsonb, deadline date, city text, pincode text check(pincode ~ '^[0-9]{6}$'), budget_min_paise bigint check(budget_min_paise>=0), budget_max_paise bigint, notes text check(char_length(notes)<=2000), pipeline text not null default 'new' check(pipeline in ('new','contacted','quote_sent','negotiation','won','lost')), version int not null default 1, quote_paise bigint check(quote_paise>=0), linked_order_id uuid unique references memocious.orders(id), check(budget_max_paise is null or budget_max_paise>=budget_min_paise));
alter table memocious.enterprise_inquiries enable row level security;
revoke all on memocious.enterprise_inquiries from public, anon, authenticated;
grant select,insert,update,delete on memocious.enterprise_inquiries to service_role;
create table memocious.request_uploads (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), user_id uuid references auth.users(id) on delete restrict, guest_session_id uuid, draft_id uuid references memocious.builder_drafts(id), custom_request_id uuid references memocious.custom_requests(id), enterprise_id uuid references memocious.enterprise_inquiries(id), review_id uuid references memocious.reviews(id), order_id uuid references memocious.orders(id), object_path text not null unique, mime text check(mime in ('image/jpeg','image/png','image/webp')), size_bytes int check(size_bytes between 1 and 5242880), width int check(width>0), height int check(height>0), content_hash text, status text not null default 'issued' check(status in ('issued','uploaded_quarantine','processing','ready_private','attached','rejected','expired','deleting','deleted')), publication_consent_at timestamptz, public_path text, expires_at timestamptz, check(num_nonnulls(draft_id,custom_request_id,enterprise_id,review_id,order_id)=1), check(num_nonnulls(user_id,guest_session_id)=1), check(width::bigint*height<=20000000));
