revoke all on memocious.consent_records from public, anon, authenticated;
grant select,insert,update,delete on memocious.consent_records to service_role;
create table memocious.audit_log (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), actor_session_id uuid, actor_kind text not null check(actor_kind in ('customer','guest','admin','operator','job')), action text not null, entity text not null, entity_id uuid, request_id uuid not null, redacted_diff jsonb not null default '{}');
alter table memocious.audit_log enable row level security;
revoke all on memocious.audit_log from public, anon, authenticated;
grant select,insert,update,delete on memocious.audit_log to service_role;
alter table memocious.builder_drafts add constraint submitted_request_fk foreign key(submitted_request_id) references memocious.custom_requests(id);
alter table memocious.orders add constraint actor_session_fk foreign key(actor_session_id) references memocious_private.app_sessions(id);
revoke update,delete,truncate on memocious.audit_log from service_role;
revoke update,delete,truncate on memocious.order_events from service_role;
revoke update,delete,truncate on memocious.order_items from service_role;
create table public.memocious_catalogue_products (id uuid primary key, slug text not null unique, data jsonb not null, search_vector tsvector not null, price_paise bigint, featured boolean not null, created_at timestamptz not null, avg_rating numeric, review_count int not null default 0);
create table public.memocious_taxonomy_items (id uuid primary key, kind text not null check(kind in ('category','occasion')), slug text not null, label text not null, parent_slug text, icon text not null, sort_order int not null, unique(kind,slug));
alter table public.memocious_catalogue_products enable row level security;
revoke all on public.memocious_catalogue_products from public,anon,authenticated;
grant select on public.memocious_catalogue_products to anon,authenticated;
grant all on public.memocious_catalogue_products to service_role;
create policy published_read on public.memocious_catalogue_products for select to anon,authenticated using (true);
alter table public.memocious_taxonomy_items enable row level security;
revoke all on public.memocious_taxonomy_items from public,anon,authenticated;
grant select on public.memocious_taxonomy_items to anon,authenticated;
grant all on public.memocious_taxonomy_items to service_role;
create policy published_read on public.memocious_taxonomy_items for select to anon,authenticated using (true);
create index catalogue_search_idx on public.memocious_catalogue_products using gin(search_vector);
create index catalogue_price_idx on public.memocious_catalogue_products(price_paise,id);
create index catalogue_created_idx on public.memocious_catalogue_products(created_at desc,id);
create index products_0_idx on memocious.products (price_paise,id) where active and deleted_at is null;
create index products_1_idx on memocious.products using gin(search_vector);
create index categories_0_idx on memocious.categories (parent_id);
create index occasions_0_idx on memocious.occasions (parent_id);
create index product_categories_0_idx on memocious.product_categories (category_id,product_id);
create index product_occasions_0_idx on memocious.product_occasions (occasion_id,product_id);
create index product_images_0_idx on memocious.product_images (product_id,sort_order);
create index product_options_0_idx on memocious.product_options (product_id);
create index option_values_0_idx on memocious.option_values (option_id);
create index orders_0_idx on memocious.orders (user_id,created_at desc);
create index orders_1_idx on memocious.orders (status,updated_at);
create index orders_2_idx on memocious.orders (actor_session_id);
create index order_events_0_idx on memocious.order_events (order_id,created_at);
create index order_items_0_idx on memocious.order_items (order_id);
create index builder_drafts_0_idx on memocious.builder_drafts (user_id,updated_at);
create index notification_outbox_0_idx on memocious.notification_outbox (status,available_at);
create index jobs_0_idx on memocious.jobs (status,available_at);
create index upload_jobs_0_idx on memocious.upload_jobs (status,available_at);
create index request_uploads_0_idx on memocious.request_uploads (user_id,status);
create index audit_log_0_idx on memocious.audit_log (created_at desc,id);
